 IF EXISTS(SELECT 1 FROM rrc217_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC217 exact pre/postimage mismatch'; END IF;
 IF (SELECT COUNT(*)FROM tradeskill_recipe WHERE id IN(2371))<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC217 recipe cardinality drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc217_after e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC217 exact pre/postimage mismatch'; END IF;
 IF (SELECT COUNT(*)FROM tradeskill_recipe_entries WHERE recipe_id IN(2371))<>7 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC217 entry cardinality drift'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries WHERE item_id IN(58182) AND successcount>0 AND iscontainer=0 AND recipe_id NOT IN(2371)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC217 manufactured output-use universe changed'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries a JOIN tradeskill_recipe r ON r.id=a.recipe_id WHERE a.item_id=58211 AND a.componentcount>0 AND a.iscontainer=0 AND r.id<>2371 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0)=3 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=58065)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=58138)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=58211)=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC217 all-state/all-skill corrected input collision'; END IF;
 IF (SELECT COUNT(*)FROM tradeskill_recipe)<>recipes_before OR(SELECT COUNT(*)FROM tradeskill_recipe_entries)<>entries_before THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC217 unexpected row-count delta'; END IF;
 DROP TEMPORARY TABLE rrc217_after;
 DROP TEMPORARY TABLE rrc217_before;
 DROP TEMPORARY TABLE rrc217_recipes;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT CONVERT(0x525243323137 USING utf8mb4) AS batch,changed_rows AS changed_rows,recipes_before,(SELECT COUNT(*)FROM tradeskill_recipe)AS recipes_after,entries_before,(SELECT COUNT(*)FROM tradeskill_recipe_entries)AS entries_after,@@in_transaction AS in_transaction;
END//
DELIMITER ;
